  g=MatchFixture();g.Players[1].ActiveSecrets.Add("EX1_594");g.Players[1].SecretCount=1;attacker=g.Summon(0,"VAN_CS2_182");attacker.SummonTurn=0;Check(g.Attack(0,attacker.Id,new MatchTarget(1)).Success&&g.Players[0].Board.Count==0&&g.Players[1].Health==30&&g.Players[1].SecretCount==0,"Vaporize destroys an attacking minion aimed at the hero");
  g=MatchFixture();g.Players[1].ActiveSecrets.Add("EX1_533");g.Players[1].SecretCount=1;attacker=g.Summon(0,"VAN_CS2_182");attacker.SummonTurn=0;Check(g.Attack(0,attacker.Id,new MatchTarget(1)).Success&&g.Players[1].Health==30&&g.Players[1].SecretCount==0,"Misdirection redirects an enemy attack to another character");
  g=MatchFixture();var view=LanProtocol.ReadView(catalog,LanProtocol.Copy(LanProtocol.View(g,1,"secret-count",0)));Check(view.Players.All(p=>p.SecretCount==0),"Secret public counters survive snapshot round trip");
